SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, COUNT_IF(status = 'FAILED') AS failed_events, MAX(paid_at) AS ended_at, SIZE(COLLECT_SET(status)) AS num_status, COUNT_IF(method = 'card') AS card_events, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count FROM payments GROUP BY DATE_TRUNC('QUARTER', paid_at) HAVING COUNT(CASE WHEN status = 'FAILED' THEN 1 END) < 1
